const test=require('node:test');const assert=require('node:assert/strict');global.window=global;require('../../reda-2/data.js');require('../../reda-2/clinical-model-v2.js');require('../../reda-2/clinical-addons.js');require('../../reda-2/motion-specs.js');require('../../reda-2/motion-legacy.js');require('../../reda-2/exercise-graph.js');
test('every exercise variant has one stable graph node and motion spec',()=>{let variants=0;for(const e of RedaData.exercises)for(const v of e.variants){variants++;const n=RedaGraph.node(e.id,v.id);assert.ok(n,e.id+'.'+v.id);assert.equal(v.pose,n.motion);assert.ok(RedaMotionSpecs.get(n.motion),'missing motion '+n.motion);}assert.equal(Object.keys(RedaGraph.nodes).length,variants);});
test('graph is clinician only and edges are reciprocal within families',()=>{assert.equal(RedaGraph.progression,'clinician_only');for(const n of Object.values(RedaGraph.nodes)){assert.ok(!n.next.includes(n.id));for(const id of n.next){const x=RedaGraph.nodes[id];assert.equal(x.family,n.family);assert.ok(x.previous.includes(n.id));assert.ok(x.rank>n.rank);}}});
test('motion specs are versioned and explicitly unreviewed prototypes',()=>{for(const s of Object.values(RedaMotionSpecs.specs)){assert.equal(s.version,1);assert.equal(s.review,'prototype-review-required');assert.ok(s.label);assert.ok(s.kind);}});
test('bridge family spans adapted start through unilateral external load',()=>{const f=RedaGraph.family('bridge'),ids=f.map(x=>x.id);for(const id of ['bridge.elevated','bridge.low','bridge.pause','bridge.band','bridge.loaded','bridge.single','bridge.single_loaded'])assert.ok(ids.includes(id),id);assert.ok(f.length>=7);assert.equal(f[0].id,'bridge.elevated');assert.equal(f.at(-1).id,'bridge.single_loaded');});
test('sit to stand separates height support tempo and external load',()=>{const ids=RedaGraph.family('sit_to_stand').map(x=>x.id);for(const id of ['chair.high','chair.support','chair.free','chair.tempo','chair.loaded'])assert.ok(ids.includes(id),id);});
test('expanded variants keep clinical dose and instruction ownership',()=>{for(const id of ['bridge','chair','calf','step_up','split_squat','rotation','scaption']){const e=RedaData.exercises.find(x=>x.id===id);assert.ok(e,id);for(const v of e.variants){assert.ok(v.steps.length>=3,id+'.'+v.id);assert.ok(v.cue);assert.ok(v.dose.sets>=1);assert.ok(v.dose.rest>=0);}}});
